def module_holisticrepair20(c):
    rows=[]
    for n,seedoff,tr in ((64,720,(0,0,0)),(80,760,(3,-2,1)),(96,800,(-3,2,1))):
      setup=_holistic_setup20(c,n,seedoff,tr);clean=[]
      for lab in ('A','B'):
        g=_holistic_grid20(setup,lab,0,0.0);clean.append((lab,_evolve_grids20(c,[g],setup['clock'],512 if n<96 else 576)[0]))
      cents={lab:_lean_macro20(c.B,g,False)[0] for lab,(g,clk) in clean}
      for lab,(g,clk) in clean:
        pts=np.argwhere(c.B.occupancy(g));rng=np.random.default_rng(c.cfg.seed+1330000+n+(lab=='B'));sel=rng.choice(len(pts),size=max(1,int(0.15*len(pts))),replace=False);dam=g.copy()
        for q in pts[sel]:dam[tuple(map(int,q))]=0
        for mode in ('free_relax','same_class_cue'):
            c.check_budget('HOLISTICREPAIR20X');u=_new_u_with_clock(c,dam,clk)
            if mode=='same_class_cue':
                cue=_holistic_grid20(setup,lab,7,0.70);mask=(cue!=setup['base']);_mask_both_grids20(u,mask,cue)
            trace=[]
            for t in range(1025):
                if t in (0,64,128,256,512,1024):
                    v,rec=_lean_macro20(c.B,c.B.g3d(u).copy(),False);trace.append({'tick':t,'distance_to_A':float(np.linalg.norm(v-cents['A'])),'distance_to_B':float(np.linalg.norm(v-cents['B'])),**rec})
                if t<1024:c.api.advance(u,1)
            rows.append({'n':n,'label':lab,'mode':mode,'damaged_cells':len(sel),'trace':trace})
    return {'trials':rows,'analysis_contract':['Free relaxation tests autonomous recovery; same-class cue is an explicitly assisted control.','Recovery means return toward the pre-damage basin metrics, not biological healing.'],'scientific_verdicts_emitted':False}

def _rehab_branch21(c,state,clock,center,pulses,sham_center=None,cycles=0):
    u=_new_u_with_clock(c,state,clock);n=state.shape[0]
    for cy in range(int(cycles)):
        cc=center if sham_center is None else sham_center;p=_canonical_v1(c,n,(cc-np.array([0,0,14]))%n,(0,0,1),8);_overlay_grid_both21(u,p,only_empty=True);c.api.advance(u,64)
    return u

def module_trainedrepair21(c):
    B=c.B;n=96;ut,uc,centers,ifaces,train=_train_routes_state21(c,n,(8,0,0));trained=B.g3d(ut).copy();trained_clock=_clock_copy(ut);control=B.g3d(uc).copy();control_clock=_clock_copy(uc);damaged,mask=_damage_route21(c,trained,centers[0],0.25,c.cfg.seed+232000);rows=[]
    for mode,cycles in (('no_rehab',0),('rehab4',4),('rehab16',16),('sham16',16)):
        c.check_budget('TRAINEDREPAIR21X');u=_rehab_branch21(c,damaged,trained_clock,centers[0],8,centers[2] if mode=='sham16' else None,cycles);v=_new_u_with_clock(c,control,control_clock)
        if cycles:c.api.advance(v,64*cycles)
        g=B.g3d(u).copy();gc=B.g3d(v).copy();roi=_roi_mask(B,n,centers[0],10);pr=_probe_state_channel(c,g,_clock_copy(u),gc,_clock_copy(v),centers[0],n,2,96);rows.append({'mode':mode,'cycles':cycles,'removed_voxels':int(np.count_nonzero(mask)),'distance_to_pre_damage_trained_state':int(_grid_hamming(g,trained,roi)),'local_state_vs_virgin':int(_grid_hamming(g,gc,roi)),'functional_gain':float(pr['gain']),'trained_peak':float(pr['trained_peak']),'virgin_peak':float(pr['virgin_peak'])})
    return {'trials':rows,'analysis_contract':['Combines structural damage with repeated retraining; success is rehabilitation toward a pre-damage functional/state reference, not spontaneous repair.','Sham retraining on another route controls for generic activity.'],'scientific_verdicts_emitted':False}

def module_homeostaticmembrane21(c):
    B=c.B;rows=[]
    for n in (64,80):
      center=np.array([n//2]*3);target=E['_v13_target_grid'](c,n,'cavity16',center);open_shell=_target_shell20c(c,n,center,10,0,-1,1);closed_shell=_target_shell20c(c,n,center,10,None,-1,0);apmask=B.occupancy(closed_shell)&~B.occupancy(open_shell)
      for stress_count in (4,16,32):
        c.check_budget('HOMEOSTATICMEMBRANE21X');uo=_new_u(c,_merge(c,target,open_shell));uc=_new_u(c,_merge(c,target,closed_shell));un=_new_u(c,_merge(c,target,open_shell));trace=[]
        for cy in range(8):
            pulses=[]
            for i in range(stress_count):pulses.append(_canonical_v1(c,n,(center-np.array([16+2*i,0,0]))%n,(1,0,0),16))
            stress=_merge(c,*pulses);_overlay_grid_both21(uo,stress,True);_overlay_grid_both21(uc,stress,True)
            for _ in range(128):c.api.advance(uo,1);c.api.advance(uc,1);c.api.advance(un,1)
            go=B.g3d(uo).copy();gc=B.g3d(uc).copy();gn=B.g3d(un).copy();trace.append({'cycle':cy+1,'open_target':_readout(B,go,center,9),'closed_target':_readout(B,gc,center,9),'no_stress_target':_readout(B,gn,center,9),'open_aperture_occupancy':int(np.count_nonzero(B.occupancy(go)&apmask)),'closed_aperture_occupancy':int(np.count_nonzero(B.occupancy(gc)&apmask))})
        rows.append({'n':n,'stress_pulses_per_cycle':stress_count,'cycles':trace})
    return {'trials':rows,'analysis_contract':['Uses repeated high-load pulses but does not assume s_reg>=9 is universally lethal.','Tests whether an initially open membrane changes its aperture under sustained load and whether that correlates with target preservation relative to always-open/always-closed controls.','Native homeostasis requires state-dependent self-gating; mere survival is insufficient.'],'scientific_verdicts_emitted':False}

