def _damage_masks(grid: np.ndarray, frac: float, seed: int) -> dict:
    occ=unpack_fields(grid)["state"]>0;coords=np.argwhere(occ);count=max(1,int(round(frac*len(coords)))) if len(coords) else 0
    if count==0:return {"random":np.zeros_like(occ),"compact":np.zeros_like(occ)}
    rng=np.random.default_rng(int(seed));pick=rng.choice(len(coords),size=min(count,len(coords)),replace=False);rm=np.zeros_like(occ);rm[tuple(coords[pick].T)]=True
    lmask,cmeta=_periodic_components_6(occ);cm=np.zeros_like(occ)
    if lmask is not None and np.any(lmask):
        lc=np.argwhere(lmask);x,center=_circular_unwrap(lc,grid.shape[0]);dist=np.linalg.norm(x,axis=1);sel=np.argsort(dist)[:min(count,len(lc))];cm[tuple(lc[sel].T)]=True
    else:cm=rm.copy()
    return {"random":rm,"compact":cm}

def _module_d7_basin_robustness(args: argparse.Namespace, budget: Budget, work: Path, d2: Mapping[str,Any]) -> dict:
    rows=[];candidates=list(d2.get("rows",[]))[:1 if args.smoke else int(args.damage_finalists)]
    ticks=8 if args.smoke else int(args.damage_ticks)
    checkpoints=sorted(set([0,1,4,8,ticks//4,ticks//2,ticks]))
    for ci,r in enumerate(candidates):
        sp=work/"snapshots"/(str(r["world_id"])+".npz");g,c,meta=_load_snapshot_npz(sp);n=g.shape[0]
        masks=_damage_masks(g,0.05,args.seed+71000+ci)
        branches={"control":(g.copy(),c.copy())}
        for kind,m in masks.items():
            gg=g.copy();cc=c.copy();gg[m]=np.uint64(0);cc[m]=np.uint64(0);branches[kind]=(gg,cc)
        universes={k:clone_from_snapshot(n,args.threads,gg,cc,int(meta.get("ticks_executed",0))) for k,(gg,cc) in branches.items()}
        traces={k:[] for k in universes}
        for t in range(ticks+1):
            budget.check("D7/damage")
            if t in checkpoints:
                for k,u in universes.items():traces[k].append({"tick":t,"analysis":_snapshot_analysis(grid3(u),clock3(u),deep=False),"combined_sha256":_combined_hash_arrays(grid3(u),clock3(u))})
            if t<ticks:
                for u in universes.values():tick_one(u)
        control={x["tick"]:x for x in traces["control"]}
        comp={}
        for kind in ("random","compact"):
            comp[kind]=[]
            for x in traces[kind]:
                ca=control[x["tick"]]["analysis"];comp[kind].append({"tick":x["tick"],"descriptor_distance_to_undamaged_control":_descriptor_distance(x["analysis"],ca),"exact_full_state_equal":x["combined_sha256"]==control[x["tick"]]["combined_sha256"]})
        rows.append({"world_id":r["world_id"],"damage_fraction":0.05,"traces":traces,"comparison":comp,"interpretation":"A falling descriptor distance is basin-level relaxation toward the undamaged trajectory, not proof of biological healing or exact voxel restoration."})
    return {"status":"completed","rows":rows}

def macro_vector(s,block=4):
    g=s['grid_A'];f=unpack(g);o=f['state']>0
    # Every coordinate has an explicit meaning, not a probability of a named form.
    return np.r_[block_mean(o.astype(float),block).ravel(),(block_mean(f['sreg'].astype(float),block)/CAP).ravel(),
                 [float(o.mean()),float(f['sreg'].mean()/CAP)]]
